gated_delta_cpp_source = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;ATen/core/Error.h&gt;

constexpr int D = 128;

__global__ void gated_delta_kernel(
    const float *q_ptr,
    const float *k_ptr,
    const float *v_ptr,
    const float *alpha_ptr,
    const float *beta_ptr,
    float *o_ptr,
    float *s_ptr,
    int64_t bh_stride_qkv,
    int64_t bh_stride_v,
    int64_t bh_stride_ab,
    int64_t s_bh_stride,
    int64_t o_bh_stride,
    int64_t Seq
) {
  __shared__ float qt_shared[D];
  __shared__ float kt_shared[D];
  __shared__ float vt_shared[D];
  __shared__ float alpha_shared;
  __shared__ float beta_shared;

  int bh = blockIdx.x;
  int i = threadIdx.x;
  if (i &gt;= D) return;

  int64_t bh_offset_qk = bh * bh_stride_qkv;
  int64_t bh_offset_v = bh * bh_stride_v;
  int64_t bh_offset_ab = bh * bh_stride_ab;
  int64_t o_bh_offset = bh * o_bh_stride;
  int64_t s_bh_offset = bh * s_bh_stride;

  for (int t = 0; t &lt; Seq; t++) {
    // Load qt, kt, vt
    qt_shared[i] = q_ptr[bh_offset_qk + t * D + i];
    kt_shared[i] = k_ptr[bh_offset_qk + t * D + i];
    vt_shared[i] = v_ptr[bh_offset_v + t * D + i];
    __syncthreads();
    if (i == 0) {
      alpha_shared = alpha_ptr[bh_offset_ab + t];
      beta_shared = beta_ptr[bh_offset_ab + t];
    }
    __syncthreads();

    // Compute sk = s @ kt
    float sk = 0.0f;
    for (int j = 0; j &lt; D; j++) {
      sk += s_ptr[s_bh_offset + (int64_t)i * D + j] * kt_shared[j];
    }
    float err = sk - vt_shared[i];

    // Update s
    for (int j = 0; j &lt; D; j++) {
      float sj = s_ptr[s_bh_offset + (int64_t)i * D + j];
      s_ptr[s_bh_offset + (int64_t)i * D + j] = alpha_shared * sj - beta_shared * err * kt_shared[j];
    }
    __syncthreads();

    // Compute ot = s @ qt
    float ot = 0.0f;
    for (int j = 0; j &lt; D; j++) {
      ot += s_ptr[s_bh_offset + (int64_t)i * D + j] * qt_shared[j];
    }
    o_ptr[o_bh_offset + t * D + i] = ot;
  }
}

torch::Tensor gated_delta_hip(
    torch::Tensor q_resh,
    torch::Tensor k_resh,
    torch::Tensor v_resh,
    torch::Tensor alpha_resh,
    torch::Tensor beta_resh
) {
  TORCH_CHECK(q_resh.size(2) == 128, "Dq must be 128");
  TORCH_CHECK(v_resh.size(2) == 128, "Dv must be 128");
  int64_t B_H = q_resh.size(0);
  int64_t Seq = q_resh.size(1);
  int64_t Dq = q_resh.size(2);
  int64_t Dv = v_resh.size(2);
  auto options = q_resh.options();
  auto s = torch::zeros({B_H, Dv, Dq}, options);
  auto o = torch::empty({B_H, Seq, Dv}, options);
  int64_t bh_stride_qkv = Seq * Dq;
  int64_t bh_stride_v = Seq * Dv;
  int64_t bh_stride_ab = Seq;
  int64_t s_bh_stride = Dv * Dq;
  int64_t o_bh_stride = Seq * Dv;
  dim3 block(D);
  dim3 grid(B_H);
  hipLaunchKernelGrid(gated_delta_kernel, grid, block, 0,
                      q_resh.data_ptr&lt;float&gt;(),
                      k_resh.data_ptr&lt;float&gt;(),
                      v_resh.data_ptr&lt;float&gt;(),
                      alpha_resh.data_ptr&lt;float&gt;(),
                      beta_resh.data_ptr&lt;float&gt;(),
                      o.data_ptr&lt;float&gt;(),
                      s.data_ptr&lt;float&gt;(),
                      bh_stride_qkv,
                      bh_stride_v,
                      bh_stride_ab,
                      s_bh_stride,
                      o_bh_stride,
                      Seq);
  return o;
}
"""

gated_delta = load_inline(
    name="gated_delta",
    cpp_sources=gated_delta_cpp_source,
    functions=["gated_delta_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        head_dim_qk: int,
        head_dim_v: int,
        use_short_conv: bool = True,
        conv_kernel_size: int = 4,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim_qk = head_dim_qk
        self.head_dim_v = head_dim_v
        self.use_short_conv = use_short_conv

        # Q, K, V projections
        self.q_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)

        # Gating projections
        self.a_proj = nn.Linear(hidden_size, num_heads, bias=True)
        self.b_proj = nn.Linear(hidden_size, num_heads, bias=True)

        # Output projection
        self.o_proj = nn.Linear(num_heads * head_dim_v, hidden_size, bias=False)

        # Optional short convolution for local context
        if use_short_conv:
            self.q_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.k_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.v_conv = nn.Conv1d(
                num_heads * head_dim_v, num_heads * head_dim_v,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_v,
                padding=conv_kernel_size - 1
            )

        # Output gate with RMSNorm + SiLU
        self.g_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.o_norm = nn.LayerNorm(head_dim_v)

        # Scaling factor for keys
        self.scale = head_dim_qk ** -0.5

        self.gated_delta = gated_delta

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape
        device = x.device
        dtype = x.dtype

        # Project to Q, K, V
        q = self.q_proj(x)
        k = self.k_proj(x)
        v = self.v_proj(x)

        # Optional short convolution
        if self.use_short_conv:
            q = self.q_conv(q.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            k = self.k_conv(k.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            v = self.v_conv(v.transpose(1, 2))[:, :, :seq_len].transpose(1, 2)
            q = F.silu(q)
            k = F.silu(k)
            v = F.silu(v)

        # Reshape for multi-head attention
        q = q.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        k = k.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        v = v.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        # Compute gating values
        alpha = torch.sigmoid(self.a_proj(x))
        beta = torch.sigmoid(self.b_proj(x))

        # Scale keys
        k = k * self.scale

        # Prepare for kernel
        BH = batch_size * self.num_heads
        q_resh = q.permute(0, 2, 1, 3).contiguous().view(BH, seq_len, self.head_dim_qk)
        k_resh = k.permute(0, 2, 1, 3).contiguous().view(BH, seq_len, self.head_dim_qk)
        v_resh = v.permute(0, 2, 1, 3).contiguous().view(BH, seq_len, self.head_dim_v)
        alpha_resh = alpha.view(BH, seq_len).contiguous()
        beta_resh = beta.view(BH, seq_len).contiguous()

        # Call custom kernel
        o_heads = self.gated_delta.gated_delta_hip(q_resh, k_resh, v_resh, alpha_resh, beta_resh)

        # Reshape back
        o = o_heads.view(batch_size, self.num_heads, seq_len, self.head_dim_v).permute(0, 2, 1, 3)

        # Output normalization
        o = self.o_norm(o)

        # Output gate
        g = torch.sigmoid(self.g_proj(x))
        g = g.view(batch_size, seq_len, self.num_heads, self.head_dim_v)
        o = o * g

        # Final projection
        o = o.reshape(batch_size, seq_len, self.num_heads * self.head_dim_v)
        o = self.o_proj(o)

        return o

