from torch.utils.cpp_extension import load_inline

kda_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void kda_kernel(
    const float* __restrict__ q_ptr,
    const float* __restrict__ k_ptr,
    const float* __restrict__ v_ptr,
    const float* __restrict__ a_ptr,
    const float* __restrict__ beta_ptr,
    float* __restrict__ o_ptr,
    const int64_t N,
    const int64_t S,
    const int64_t n_stride_kq,
    const int64_t s_stride_kq,
    const int64_t n_stride_va,
    const int64_t s_stride_va,
    const int64_t s_stride_beta
) {
  const int n = blockIdx.x;
  if (n >= N) return;

  const int64_t base_k = n * n_stride_kq;
  const int64_t base_q = base_k;
  const int64_t base_v = n * n_stride_va;
  const int64_t base_a = base_v;
  const int64_t base_beta = n * S * s_stride_beta;
  const int64_t base_o = base_v;

  constexpr int DV_ = 128;
  constexpr int DQ_ = 128;
  constexpr size_t S_size = DV_ * DQ_;

  extern __shared__ float shmem[];

  float* S_shared = shmem;
  float* kt_shared = S_shared + S_size;
  float* vt_shared = kt_shared + DQ_;
  float* at_shared = vt_shared + DV_;
  float* qt_shared = at_shared + DV_;
  float* sk_shared = qt_shared + DQ_;
  float* error_shared = sk_shared + DV_;
  float* beta_shared = error_shared + DV_;

  const int tid = threadIdx.x;
  const int BS = blockDim.x;

  // Zero S_shared
  for (size_t i = tid; i < S_size; i += BS) {
    S_shared[i] = 0.0f;
  }
  __syncthreads();

  for (int64_t t = 0; t < S; t++) {
    // Load kt, qt, vt, at, beta_t
    if (tid < DQ_) {
      kt_shared[tid] = k_ptr[base_k + t * s_stride_kq + tid];
      qt_shared[tid] = q_ptr[base_q + t * s_stride_kq + tid];
    }
    if (tid < DV_) {
      vt_shared[tid] = v_ptr[base_v + t * s_stride_va + tid];
      at_shared[tid] = a_ptr[base_a + t * s_stride_va + tid];
    }
    if (tid == 0) {
      beta_shared[0] = beta_ptr[base_beta + t * s_stride_beta];
    }
    __syncthreads();

    // S @ k_t
    if (tid < DV_) {
      float acc = 0.0f;
#pragma unroll
      for (int j = 0; j < DQ_; j++) {
        acc += S_shared[tid * DQ_ + j] * kt_shared[j];
      }
      sk_shared[tid] = acc;
    }
    __syncthreads();

    // error = sk - vt
    if (tid < DV_) {
      error_shared[tid] = sk_shared[tid] - vt_shared[tid];
    }
    __syncthreads();

    // Update S: S *= diag(a) - beta * error outer k
    const float betat = beta_shared[0];
    for (size_t i = tid; i < S_size; i += BS) {
      const int row = i / DQ_;
      const int col = i % DQ_;
      S_shared[i] *= at_shared[row];
      S_shared[i] -= betat * error_shared[row] * kt_shared[col];
    }
    __syncthreads();

    // o_t = S @ q_t
    if (tid < DV_) {
      float acc = 0.0f;
#pragma unroll
      for (int j = 0; j < DQ_; j++) {
        acc += S_shared[tid * DQ_ + j] * qt_shared[j];
      }
      o_ptr[base_o + t * s_stride_va + tid] = acc;
    }
  }
}

torch::Tensor kda_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, torch::Tensor a, torch::Tensor beta) {
  auto q_sizes = q.sizes();
  int64_t N = q_sizes[0];
  int64_t S = q_sizes[1];
  int64_t DQ = q_sizes[2];

  auto v_sizes = v.sizes();
  int64_t DV = v_sizes[2];

  torch::Tensor o = torch::empty({N, S, DV}, q.options());

  int64_t n_stride_kq = S * DQ;
  int64_t s_stride_kq = DQ;
  int64_t n_stride_va = S * DV;
  int64_t s_stride_va = DV;
  int64_t s_stride_beta = 1;

  const int block_size = 256;
  dim3 grid(N);
  dim3 block(block_size);

  int SH_DQ = 128;
  int SH_DV = 128;
  size_t shmem_size = sizeof(float) * (SH_DV * SH_DQ + 2 * SH_DQ + 4 * SH_DV + 16);

  hipStream_t stream = 0;
  hipLaunchKernelGQL(
      kda_kernel,
      grid,
      block,
      shmem_size,
      stream,
      q.data_ptr<float>(),
      k.data_ptr<float>(),
      v.data_ptr<float>(),
      a.data_ptr<float>(),
      beta.data_ptr<float>(),
      o.data_ptr<float>(),
      N, S,
      n_stride_kq, s_stride_kq,
      n_stride_va, s_stride_va,
      s_stride_beta
  );

  return o;
}
"""

